package ama.storage;

import java.io.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.math.BigInteger;
import static org.junit.jupiter.api.Assertions.*;import static ama.storage.Task11B2ExactRetryOracle.*;

/** Exact full-row delta for one READY0/PREPARED never-marked decision. No row, actor or write authority. */
final class Task11B3LocalOracle {
 static Map<String,Object> row(Map<String,List<Map<String,Object>>> rows,String table,String field,String id){var matches=rows.get(table).stream().filter(r->id.equals(r.get(field))).toList();assertEquals(1,matches.size(),table+" exact selected row");return matches.getFirst();}
 static List<Object> identity(Map<String,Object> row,List<String> keys){assertNotNull(keys);assertFalse(keys.isEmpty());for(String key:keys)assertTrue(row.containsKey(key));return keys.stream().map(k->canonical(row.get(k))).toList();}
 static Map<String,Object> without(Map<String,Object> row,Set<String> allowed){var value=new TreeMap<>(row);allowed.forEach(value::remove);return value;}
 static String digest(String... values)throws Exception {var bytes=new ByteArrayOutputStream();var out=new DataOutputStream(bytes);for(String value:values){byte[] b=value.getBytes(StandardCharsets.UTF_8);out.writeInt(b.length);out.write(b);}return Task11B2RuntimeFixture.digest(bytes.toByteArray());}
 static Map<String,Object> verify(Map<String,List<Map<String,Object>>> before,Map<String,List<Map<String,Object>>> after,Map<String,List<String>> primaryKeys,String meeting,String publication,String task,String execution,String operation,String owner,String key)throws Exception {
  var expected=new HashSet<>(TABLES);expected.addAll(Set.of("model_capacity","model_reservation"));assertEquals(expected,before.keySet());assertEquals(expected,after.keySet());
  var allowed=Map.of("meeting",Set.of("stage","updated_at"),"publication",Set.of("state","revision"),"durable_task",Set.of("state","lease_owner","expires_at","last_error","output_kind","output_id"),"external_execution",Set.of("state","finished_at","no_effect_basis","no_effect_evidence","no_effect_verified_at"),"external_operation",Set.of("state","last_error","reconcile_epoch","reconcile_owner","reconcile_expires_at"),"publication_submission",Set.of("local_state","local_decided_at","local_reason","local_decided_by","local_attempt_no","local_execution_id"),"task_outbox_sequence",Set.of("next_id"));
  var changed=Map.of("meeting",meeting,"publication",publication,"durable_task",task,"external_execution",execution,"external_operation",operation,"publication_submission",task);
  var extras=new HashMap<String,List<Map<String,Object>>>();
  for(String table:expected){
   int addition=table.equals("task_outbox")?2:Set.of("audit_event","idempotency_record").contains(table)?1:0;assertEquals(before.get(table).size()+addition,after.get(table).size(),table+" full count");
   var actual=new HashMap<List<Object>,Map<String,Object>>();for(var r:after.get(table))assertNull(actual.put(identity(r,primaryKeys.get(table)),r),"Duplicate primary identity");
   for(var old:before.get(table)){
    var found=actual.remove(identity(old,primaryKeys.get(table)));assertNotNull(found,"Immutable predecessor missing: "+table);assertEquals(old.keySet(),found.keySet(),table+" field set");
    String idField=table.equals("publication_submission")?"task_id":"id";boolean selected=table.equals("task_outbox_sequence")||changed.containsKey(table)&&changed.get(table).equals(old.get(idField));
    if(selected)equal(without(old,allowed.get(table)),without(found,allowed.get(table)));else equal(old,found);
   }
   assertEquals(addition,actual.size());extras.put(table,new ArrayList<>(actual.values()));
  }
  var root=row(after,"meeting","id",meeting);assertEquals("PUBLISH_FAILED",root.get("stage"));assertNotNull(root.get("updated_at"));assertEquals(owner,root.get("owner_id"));
  var pub=row(after,"publication","id",publication);assertEquals("FAILED",pub.get("state"));assertEquals(integer(row(before,"publication","id",publication).get("revision")).add(BigInteger.ONE),integer(pub.get("revision")));
  var t=row(after,"durable_task","id",task);assertEquals("FAILED",t.get("state"));assertEquals("EXPIRED_UNMARKED_ABANDONED",t.get("last_error"));assertEquals(BigInteger.ZERO,integer(t.get("attempt")));for(String field:List.of("lease_owner","expires_at","output_kind","output_id"))assertNull(t.get(field));
  var ex=row(after,"external_execution","id",execution);assertEquals("FAILED",ex.get("state"));assertEquals("NOT_SENT",ex.get("no_effect_basis"));assertEquals("publication-local:"+task,ex.get("no_effect_evidence"));assertNotNull(ex.get("finished_at"));assertNotNull(ex.get("no_effect_verified_at"));equal(ex.get("finished_at"),ex.get("no_effect_verified_at"));assertNull(ex.get("marked_at"));assertNull(ex.get("task_attempt"));
  var op=row(after,"external_operation","id",operation);assertEquals("FAILED",op.get("state"));assertEquals("LOCAL_NEVER_MARKED",op.get("last_error"));assertEquals(integer(row(before,"external_operation","id",operation).get("reconcile_epoch")).add(BigInteger.ONE),integer(op.get("reconcile_epoch")));assertNull(op.get("reconcile_owner"));assertNull(op.get("reconcile_expires_at"));
  var sub=row(after,"publication_submission","task_id",task);assertEquals("NEVER_MARKED",sub.get("local_state"));assertEquals("EXPIRED_UNMARKED_ABANDONED",sub.get("local_reason"));assertEquals(owner,sub.get("local_decided_by"));assertEquals(BigInteger.ZERO,integer(sub.get("local_attempt_no")));assertEquals(execution,sub.get("local_execution_id"));assertNotNull(sub.get("local_decided_at"));
  assertEquals(1,before.get("task_outbox_sequence").size());assertEquals(1,after.get("task_outbox_sequence").size());BigInteger next=integer(before.get("task_outbox_sequence").getFirst().get("next_id"));assertEquals(next.add(BigInteger.TWO),integer(after.get("task_outbox_sequence").getFirst().get("next_id")));
  var outboxes=extras.get("task_outbox");assertEquals(Set.of("TASK_FAILED","PUBLICATION_LOCAL_RECOVERED"),new HashSet<>(outboxes.stream().map(r->r.get("event_type")).toList()));assertEquals(Set.of(next,next.add(BigInteger.ONE)),new HashSet<>(outboxes.stream().map(r->integer(r.get("sequence_id"))).toList()));
  for(var outbox:outboxes){assertEquals(before.get("task_outbox").getFirst().keySet(),outbox.keySet());assertEquals(task,outbox.get("task_id"));assertEquals("MEETING",outbox.get("subject_kind"));assertEquals(meeting,outbox.get("subject_id"));assertEquals(integer(root.get("revision")),integer(outbox.get("subject_revision")));assertEquals("PUBLICATION",outbox.get("reference_kind"));assertEquals(publication,outbox.get("reference_id"));assertNotNull(outbox.get("occurred_at"));}
  var audit=extras.get("audit_event").getFirst();assertEquals(before.get("audit_event").getFirst().keySet(),audit.keySet());assertEquals("PUBLICATION_LOCAL_NEVER_MARKED",audit.get("action"));assertEquals(owner,audit.get("actor_id"));assertEquals(meeting,audit.get("resource_id"));assertEquals(integer(root.get("revision")),integer(audit.get("revision")));assertEquals("SUCCEEDED",audit.get("result"));assertNotNull(audit.get("occurred_at"));BigInteger auditId=integer(audit.get("id"));assertTrue(auditId.signum()>0&&auditId.bitLength()<=64,"Audit id must be a positive unsigned BIGINT");assertTrue(audit.get("trace_id").toString().matches("[0-9a-f-]{36}"));
  var receipt=extras.get("idempotency_record").getFirst();assertEquals(before.get("idempotency_record").getFirst().keySet(),receipt.keySet());assertEquals("PUBLICATION_LOCAL_RECOVERY",receipt.get("operation"));assertEquals(owner,receipt.get("actor_id"));assertEquals(meeting,receipt.get("resource_id"));assertEquals(task,receipt.get("result_id"));assertEquals("SUCCEEDED",receipt.get("state"));assertEquals(BigInteger.valueOf(200),integer(receipt.get("http_status")));assertNotNull(receipt.get("created_at"));assertEquals(digest(key),receipt.get("key_hash"));assertEquals(digest(owner,meeting,"PUBLICATION_LOCAL_RECOVERY",key),receipt.get("scope_hash"));assertEquals(digest(publication,task,integer(root.get("revision")).toString(),integer(row(before,"publication","id",publication).get("revision")).toString()),receipt.get("request_hash"));
  return Map.of("task",t,"submission",sub,"execution",ex,"operation",op,"publication",pub,"meeting",root,"receipt",receipt,"audit",audit,"outbox",outboxes);
 }
}